/* Buildless, offline-first educational prototype. No network requests. */
const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
// A small URL-fragment handoff keeps separate file:// pages working even when
// a browser isolates localStorage by filename. Fragments are not server requests.
const memoryState=Object.create(null);
try {
 if(typeof location!=='undefined'){
  const token=new URLSearchParams(location.hash.slice(1)).get('studio');
  if(token&&token.length<12000){
   const h=JSON.parse(token),keys=['mouse','pigs','chickens'];
   memoryState['dongho-language']='en';
   if(Number.isInteger(h.historyChapter)&&h.historyChapter>=0&&h.historyChapter<HERITAGE_CHAPTERS.length)memoryState['dongho-history-chapter']=h.historyChapter;
   if(['free','print'].includes(h.creation))memoryState['dongho-creation-mode']=h.creation;
   if(['drawing','print'].includes(h.exhibitKind))memoryState['dongho-exhibit-kind']=h.exhibitKind;
   if(keys.includes(h.selected))memoryState['dongho-selected']=h.selected;
   if(typeof h.large==='boolean')memoryState['dongho-large']=h.large;
   if(h.work&&keys.includes(h.work.art)&&Number.isInteger(h.work.stage)&&h.work.stage>=0&&h.work.stage<=4&&Number.isInteger(h.work.layers)&&h.work.layers>=0&&h.work.layers<=5){
    const w=h.work;
    memoryState['dongho-studio']={stage:w.stage,art:w.art,coated:!!w.coated,inspected:Array.isArray(w.inspected)?[...new Set(w.inspected.filter(i=>Number.isInteger(i)&&i>=0&&i<5))]:[],layers:w.layers,mode:w.mode==='independent'?'independent':'guided',block:Number.isInteger(w.block)?Math.max(0,Math.min(4,w.block)):0,offsetX:Number.isFinite(w.offsetX)?Math.max(-45,Math.min(45,w.offsetX)):14,offsetY:Number.isFinite(w.offsetY)?Math.max(-45,Math.min(45,w.offsetY)):-10};
   }
   if(h.completed&&keys.includes(h.completed.art))memoryState['dongho-completed']={art:h.completed.art,name:typeof h.completed.name==='string'?h.completed.name.slice(0,50):'',date:typeof h.completed.date==='string'?h.completed.date.slice(0,40):''};
  }
 }
}catch{}
const safeGet = (key, fallback) => {if(Object.prototype.hasOwnProperty.call(memoryState,key))return memoryState[key];try {return JSON.parse(localStorage.getItem(key)) ?? fallback;} catch {return fallback;}};
const save = (key, value) => {
 memoryState[key]=value;
 try {localStorage.setItem(key,JSON.stringify(value));}catch{}
 try {
  if(typeof location!=='undefined'&&location.protocol==='file:'&&window.history?.replaceState){
   const file=location.pathname.split(/[\\/]/).pop()||routes[page];
   const params=new URLSearchParams(location.hash.slice(1));params.delete('create');
   window.history.replaceState(null,'',buildStudioDestination(file+'#'+params.toString()));
  }
 }catch{}
};
// Persist an arriving handoff in this particular HTML page's storage bucket.
for(const [key,value] of Object.entries(memoryState)){try{localStorage.setItem(key,JSON.stringify(value));}catch{}}
let lang = 'en';
const t = en => en;
const esc = value => String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let page = document.body.dataset.page || 'home';
const routes = {home:'HomePage.html',history:'HistoryPage.html',explore:'ExplorePage.html',workshop:'WorkshopPage.html',exhibition:'ExhibitionPage.html'};
const names = ()=>({home:'The studio',history:'History',explore:'Art & Symbols',workshop:'Create',exhibition:'My Gallery'});
const artwork = {
 mouse:{vi:'Mouse Wedding',en:'Mouse Wedding',difficulty:['Curious beginner','Người mới tò mò'],desc:['A joyful procession. A powerful cat. A story hiding in plain sight.','Một đám cưới vui vẻ. Một chú mèo quyền thế. Một câu chuyện ẩn trong tranh.'],meaning:['Often read as a witty comment on unequal power: mice bring gifts to a cat before their wedding can proceed. This is a common interpretation, rather than a record of a real event.','Thường được đọc như lời châm biếm quyền lực bất bình đẳng: chuột mang lễ cho mèo để đám cưới diễn ra yên ổn. Đây là cách diễn giải phổ biến, không phải ghi chép sự kiện thật.'],alt:['Study illustration of two rows of mice, a wedding procession below and gift bearers facing a large cat above.','Minh họa nghiên cứu hai hàng chuột: đoàn rước dâu phía dưới, đoàn dâng lễ đối diện mèo lớn phía trên.'],details:[
 {x:81,y:30,title:['The cat & the powerful','Mèo và kẻ có quyền'],body:['Why is a cat invited to a mouse wedding? In a familiar reading, the cat stands for those with power. Its imposing scale makes the imbalance visible before a single word is read.','Vì sao mèo xuất hiện trong đám cưới chuột? Trong cách đọc quen thuộc, mèo tượng trưng cho kẻ có quyền. Kích thước lớn cho thấy sự chênh lệch trước cả khi đọc lời giải thích.']},
 {x:38,y:26,title:['Gifts with a second meaning','Lễ vật và tầng nghĩa'],body:['The upper procession brings offerings. Read together with the cat, these gifts are often interpreted as bribery: humor makes a difficult social criticism easier to share.','Đoàn chuột phía trên mang lễ vật. Khi đặt cạnh hình ảnh mèo, lễ vật thường được hiểu là sự đút lót: tiếng cười giúp lời phê phán xã hội dễ đi vào lòng người.']},
 {x:53,y:68,title:['A wedding carries on','Đám cưới vẫn tiếp diễn'],body:['The lower procession brings the wedding into view. Repeated figures and a shared direction give the composition rhythm. Look for the contrast between celebration and negotiation.','Đoàn rước phía dưới kể chuyện cưới hỏi. Nhân vật lặp lại, cùng một hướng tạo nhịp điệu cho bố cục. Hãy tìm sự tương phản giữa niềm vui và việc thương lượng.']}]},
 pigs:{vi:'Yin-Yang Pig Family',en:'Yin-Yang Pig Family',difficulty:['Gentle first print','Bản in khởi đầu'],desc:['Rounded forms and little piglets hold a wish for an abundant life.','Dáng lợn tròn đầy và đàn con gửi gắm ước vọng cuộc sống sung túc.'],meaning:['A common reading connects the full-bodied pigs and their young with prosperity and family abundance. Meanings also grow out of the lived experience of farming.','Cách đọc phổ biến liên hệ đàn lợn đầy đặn với sự sung túc và gia đình đông vui. Ý nghĩa cũng bắt nguồn từ kinh nghiệm chăn nuôi trong đời sống.'],alt:['Study illustration of a large pig with a yin-yang spiral, four piglets, and a green plant.','Minh họa nghiên cứu lợn mẹ có xoáy âm dương, bốn lợn con và cây xanh.'],details:[
 {x:40,y:38,title:['The yin-yang spiral','Xoáy âm dương'],body:['These paired, curling forms are commonly described as yin and yang. They bring contrasting shapes into balance. This study emphasizes the motif; historical versions differ in their exact line work.','Những nét xoáy đối nhau thường được gọi là âm dương. Chúng tạo sự cân bằng giữa các hình đối lập. Bản nghiên cứu nhấn mạnh họa tiết; nét khắc ở các phiên bản xưa có thể khác nhau.']},
 {x:60,y:76,title:['A wish for abundance','Ước mong sung túc'],body:['A healthy animal and its young can evoke a well-provided household. For farming families, livestock also meant food, care, and practical prosperity. Symbolic and everyday readings can coexist.','Con vật khỏe mạnh và đàn con gợi một gia đình đủ đầy. Với nhà nông, vật nuôi còn gắn với thức ăn, sự chăm sóc và của cải. Ý nghĩa biểu tượng và đời thường có thể cùng tồn tại.']},
 {x:21,y:54,title:['Life close to the land','Cuộc sống bên ruộng vườn'],body:['Plants and domestic animals bring the countryside into the picture. Flat color and strong contours keep these familiar subjects immediately recognizable.','Cây cối và vật nuôi đưa cảnh quê vào tranh. Mảng màu phẳng và đường viền rõ khiến những hình ảnh thân thuộc dễ được nhận ra.']}]},
 chickens:{vi:'Hen and Chicks',en:'Hen and Chicks',difficulty:['Gentle first print','Bản in khởi đầu'],desc:['A mother hen and her chicks: a small scene with a generous heart.','Gà mẹ và đàn con: khung cảnh nhỏ gửi gắm tình cảm lớn.'],meaning:['The hen and chicks are commonly associated with family happiness and many children. A household scene becomes an affectionate wish for a thriving family.','Gà mẹ và đàn con thường gắn với niềm vui gia đình, con cháu đông vui. Cảnh sinh hoạt trở thành lời chúc gia đình phát triển, đầm ấm.'],alt:['Study illustration of a golden mother hen, a green tail, red comb, and five chicks.','Minh họa nghiên cứu gà mẹ vàng, đuôi xanh, mào đỏ và năm gà con.'],details:[
 {x:56,y:46,title:['At the center: care','Trung tâm là sự chăm sóc'],body:['The large hen holds the composition together. A familiar interpretation connects this mother-and-young scene with care, family happiness, and continuity.','Gà mẹ lớn giữ vai trò trung tâm bố cục. Một cách đọc quen thuộc liên hệ cảnh mẹ con với sự chăm sóc, niềm vui gia đình và tiếp nối thế hệ.']},
 {x:75,y:73,title:['Many chicks, many wishes','Đàn con, nhiều ước vọng'],body:['The small chicks repeat the same rounded shapes at a different scale. Their grouping is commonly read as a wish for a flourishing, close-knit family.','Các gà con lặp lại dáng tròn ở kích thước nhỏ hơn. Cách tụ họp thường được hiểu như lời chúc gia đình đông vui, gắn bó.']},
 {x:32,y:36,title:['A rhythm of feathers','Nhịp điệu lông gà'],body:['Look at the repeated curves in the feathers. Rhythm comes from a few confident marks, rather than realistic shading. Compare these curves with the pigs’ spiral markings.','Hãy nhìn các đường cong lặp lại ở lông gà. Nhịp điệu đến từ những nét rõ ràng thay vì tả bóng chân thực. So sánh với xoáy trên thân lợn.']}]}
};
