function header(){const n=names();return `<div class="topline"></div><header><div class="wrap nav-wrap"><a class="brand" href="HomePage.html" aria-label="Dong Ho studio home"><span><strong>Dong Ho</strong><small>The living printmaking studio</small></span></a><button class="menu" id="menu" aria-label="Open navigation" aria-expanded="false">☰</button><nav class="nav" aria-label="Main navigation">${Object.entries(n).map(([key,label])=>`<a href="${routes[key]}" ${page===key?'class="active" aria-current="page"':''}>${label}</a>`).join('')}</nav><div class="tools"><button class="tool" id="ambient" aria-pressed="${ambientOn}" title="Optional ambient sound">${ambientOn?'♫':'♩'} <span>${ambientOn?'Sound on':'Sound off'}</span></button><button class="tool text-size" id="text-size" aria-label="Toggle larger text" aria-pressed="${safeGet('dongho-large',false)}">A<span style="font-size:1rem">a</span></button></div></div></header>`;}
function sourcePanel(){return `<details class="sources" id="sources"><summary>Research, image notes & cultural context</summary><ul class="site-source-list">${heritageSourceLinks(['loan','pictorial','gallery','unesco','vov'])}</ul><p class="source-clarification">${page==='home'?'The homepage includes a CC0 museum photograph by Daderot; see the artwork credits above. Its other illustrations and animated study are contemporary reconstructions.':'The village scenes, objects, and example paintings are original vector study reconstructions.'} Visitor drawings are contemporary personal creations. Historical facts, symbolic interpretations, and reconstructed images are labeled separately.</p><p class="source-clarification">The printing lesson uses digital color masks, not recovered original blocks. It demonstrates a published red, plant-color, yellow, white, then black teaching sequence; its green-toned layer substitutes for the blue reference. Color recipes, blocks, and working methods vary by print and artisan.</p><p class="source-clarification">Compare archival examples: <a href="https://commons.wikimedia.org/wiki/File:%C4%90%C3%A1m_c%C6%B0%E1%BB%9Bi_chu%E1%BB%99t.JPG" target="_blank" rel="noopener">Mouse Wedding</a>, <a href="https://commons.wikimedia.org/wiki/File:L%E1%BB%A3n_%C3%A2m_d%C6%B0%C6%A1ng.JPG" target="_blank" rel="noopener">Yin-Yang Pig Family</a>, and <a href="https://commons.wikimedia.org/wiki/File:S%C3%A2n_g%C3%A0.JPG" target="_blank" rel="noopener">Hen and Chicks</a>.</p></details>`;}
function footer(){const supporting=page==='history'?'':`<div class="wrap"><section class="narration" aria-label="Audio and transcript"><div class="narration-bar"><button id="narrate" aria-pressed="false">▷ Listen to this page</button><span class="micro" id="voice-status">Optional English browser voice · written words always available</span></div><details><summary>Read narration transcript</summary><p class="transcript" id="transcript"></p></details></section>${sourcePanel()}</div>`;return supporting+`<footer class="footer ${page==='history'?'storybook-footer':''}"><div class="wrap footer-row"><div><p class="footer-brand">Dong Ho</p><p>A living tradition. A new way to connect.</p></div><p>An independent educational prototype · Made to learn, made to preserve.</p><div><a href="HistoryPage.html">Discover the heritage</a> ${page==='history'?'<button data-reader-sources aria-haspopup="dialog" aria-controls="history-sources">Sources & credits</button>':'<a href="#sources">Sources & credits</a>'}</div></div></footer><div id="toast" class="toast" role="status" hidden></div>`;}
function explore(){const a=artwork[selectedArt],d=a.details[selectedDetail];return `<main id="main" class="wrap"><section class="page-head"><div class="breadcrumb">Dong Ho / ${t('Explore paintings','Khám phá tranh')}</div><div class="eyebrow">${t('Look closer. There is a story.','Nhìn kỹ hơn. Có một câu chuyện.')}</div><h1>${t('Every detail has something to say.','Mỗi chi tiết đều lên tiếng.')}</h1><p>${t('Choose a painting, then tap a numbered detail. Familiar animals open a window onto Vietnamese life.','Chọn một bức tranh, rồi chạm vào chi tiết có số. Những con vật quen thuộc mở cánh cửa vào đời sống Việt.')}</p><div class="tabs" role="tablist" aria-label="${t('Choose an artwork','Chọn tác phẩm')}">${Object.entries(artwork).map(([k,v])=>`<button role="tab" id="art-tab-${k}" aria-controls="art-panel" aria-selected="${k===selectedArt}" tabindex="${k===selectedArt?0:-1}" class="tab ${k===selectedArt?'active':''}" data-art="${k}">${v.en}</button>`).join('')}</div></section><section id="art-panel" role="tabpanel" aria-labelledby="art-tab-${selectedArt}" class="split"><div><div class="art-stage"><div class="art-frame" id="explore-frame"><div id="zoom-content" style="transform:scale(${zoom});transform-origin:center;transition:transform .25s">${img(selectedArt)}${a.details.map((v,i)=>`<button class="hotspot ${i===selectedDetail?'active':''}" style="left:${v.x}%;top:${v.y}%" data-detail="${i}" aria-pressed="${i===selectedDetail}" aria-label="${i+1}. ${esc(aText(v.title))}">${i+1}</button>`).join('')}</div></div><div class="art-toolbar"><span class="micro">${t('Tap a number to look closer','Chạm một số để nhìn kỹ hơn')}</span><div><button id="zoom-out" aria-label="${t('Zoom out','Thu nhỏ')}">−</button> <span class="micro" id="zoom-label">${Math.round(zoom*100)}%</span> <button id="zoom-in" aria-label="${t('Zoom in','Phóng to')}">+</button> <button id="zoom-reset" aria-label="${t('Reset view','Đặt lại khung nhìn')}">↺</button></div></div></div><p class="art-caption">${t('Contemporary study reconstruction · inspect the archival reference in Sources below.','Minh họa nghiên cứu đương đại · xem tư liệu gốc trong mục Nguồn bên dưới.')}</p></div><aside class="detail-panel" aria-live="polite"><div class="detail-number">${t('DETAIL','CHI TIẾT')} 0${selectedDetail+1} / 03</div><h2>${aText(d.title)}</h2><p id="detail-story">${aText(d.body)}</p><span class="badge">${t('A common interpretation','Một cách diễn giải phổ biến')}</span><div class="swatches" aria-label="${t('Study palette: vermilion, green, ochre, shell white, charcoal','Bảng màu nghiên cứu: đỏ, xanh, vàng, trắng shell coating, đen')}">${['#b74732','#58734d','#d5a24b','#f8f1db','#292620'].map(c=>`<span class="swatch" style="background:${c}" aria-hidden="true"></span>`).join('')}</div><button class="text-link" id="listen-detail">▷ ${t('Listen to this detail','Nghe chi tiết này')}</button><div class="detail-list">${a.details.map((v,i)=>`<button data-detail="${i}" class="${i===selectedDetail?'active':''}" aria-pressed="${i===selectedDetail}"><span>0${i+1} &nbsp; ${aText(v.title)}</span><span aria-hidden="true">↗</span></button>`).join('')}</div></aside></section><details class="comparison"><summary>${t('Compare the three paintings: patterns, colors & meanings','So sánh ba bức tranh: họa tiết, màu sắc và ý nghĩa')}</summary><div class="compare-grid">${Object.entries(artwork).map(([k,v])=>`<article>${img(k)}<h3>${v.en}</h3><p>${aText(v.meaning)}</p></article>`).join('')}</div><p class="instruction">${t('Notice the shared flat colors and bold contours. Curves unify the animals; repeated figures build a procession or a family. These vector studies share a teaching palette, while historical print palettes vary.','Chú ý mảng màu phẳng và đường viền đậm. Đường cong thống nhất hình con vật; nhân vật lặp lại tạo đoàn rước hay gia đình. Các minh họa dùng chung bảng màu học tập; màu tranh lịch sử có thể khác nhau.')}</p></details><div class="actions"><a class="btn" href="WorkshopPage.html" id="make-this">${t('Make this painting','Thực hành bức tranh này')} →</a></div></main>`;}
const pigments=()=>[
 {key:'red',color:'#b74732',name:t('Earth red','Đỏ đất'),source:t('Red ochre','Sỏi son'),body:t('Red ochre is a documented mineral source for red. Our screen color is a visual approximation, not a pigment recipe.','Sỏi son là nguồn khoáng chất tạo màu đỏ được ghi nhận. Màu trên màn hình là mô phỏng thị giác, không phải công thức pha màu.')},
 {key:'blue',color:'#58734d',name:t('Plant color','Xanh thực vật'),source:t('Indigo reference','Tham chiếu chàm'),body:t('Indigo is a documented blue source. This study uses a green-toned plant-color substitute; it does not claim to match an original print’s pigment.','Chàm là nguồn xanh lam được ghi nhận. Minh họa dùng lớp màu thực vật thiên lục thay thế; không khẳng định khớp sắc tố của bản in gốc.')},
 {key:'yellow',color:'#d5a24b',name:t('Golden yellow','Vàng ấm'),source:t('Gardenia / flowers','Dành dành / hoa hòe'),body:t('Gardenia fruit and pagoda-tree flowers are documented yellow sources. Natural materials become part of the story before they become part of the image.','Quả dành dành và hoa hòe là nguồn màu vàng được ghi nhận. Chất liệu tự nhiên trở thành một phần câu chuyện trước khi thành một phần hình ảnh.')},
 {key:'white',color:'#f8f1db',name:t('Shell white','Trắng shell coating'),source:t('Powdered shells','Bột vỏ sò'),body:t('Weathered shells provide white; shell powder also belongs to the special paper coating. Paper preparation and a white color impression are distinct steps.','Vỏ sò phong hóa tạo sắc trắng; bột vỏ sò cũng nằm trong lớp quét giấy. Chuẩn bị nền giấy và in một lớp màu trắng là hai công đoạn khác nhau.')},
 {key:'black',color:'#292620',name:t('Bamboo black','Đen tre'),source:t('Burnt bamboo leaves','Lá tre đốt'),body:t('Burnt bamboo leaves are a documented black source. The final black impression brings the contours into focus, completing the print.','Lá tre đốt là nguồn màu đen được ghi nhận. Lớp in đen cuối cùng làm rõ đường viền và hoàn thiện bản tranh.')}
];
let pigmentIndex=0;
function stepContent(){const a=artwork[studio.art],ps=pigments();
 if(studio.stage===0)return `<div class="work-title"><div><h2>${t('Which story will you print?','Bạn sẽ in câu chuyện nào?')}</h2><p>${t('Three studies. Three ways into a tradition. Choose one to begin.','Ba bản nghiên cứu. Ba lối vào truyền thống. Chọn một bức để bắt đầu.')}</p></div><span class="micro">${t('About 5–8 minutes','Khoảng 5–8 phút')}</span></div><div class="painting-choices">${Object.entries(artwork).map(([k,v])=>`<button class="painting-choice ${k===studio.art?'active':''}" data-choose="${k}" aria-pressed="${k===studio.art}">${img(k)}<div><h3>${v.en}</h3><p>${aText(v.desc)}</p><small>${aText(v.difficulty)} · ${t('5 color layers','5 lớp màu')}</small></div>${k===studio.art?'<span class="selection-tick" aria-hidden="true">✓</span>':''}</button>`).join('')}</div>`;
 if(studio.stage===1)return `<div class="work-title"><div><h2>${t('Give the colors a place to live.','Tạo một nơi cho màu sắc ở lại.')}</h2><p>${t('Prepare a sheet of virtual bark paper with its characteristic shell coating.','Chuẩn bị tờ giấy bark ảo với lớp quét shell coating đặc trưng.')}</p></div></div><div class="split"><div class="paper-table"><div class="paper-preview ${studio.coated?'coated':''}" id="paper-preview">${studio.coated?t('Coated paper · ready to print','Coated paper · đã sẵn sàng'):t('Bark paper · uncoated','Bark paper · chưa quét shell coating')}</div><span class="brush" aria-hidden="true">▰</span></div><div class="panel"><div class="eyebrow">${t('The paper is part of the art','Giấy cũng là một phần nghệ thuật')}</div><h3 style="margin-top:18px">${t('A surface with a soft shimmer.','Bề mặt óng ánh dịu nhẹ.')}</h3><p>${t('Powdered shells in the shell coating give the paper a distinctive surface. In a real workshop, this coating is brushed on by hand.','Bột vỏ sò trong lớp quét shell coating tạo bề mặt đặc trưng cho giấy. Ở xưởng thật, lớp phủ này được quét bằng tay.')}</p><div class="actions"><button class="btn" id="coat" ${studio.coated?'disabled':''}>${studio.coated?'✓ '+t('Paper prepared','Giấy đã chuẩn bị'):t('Brush on the shell coating','Quét lớp shell coating')}</button></div><p class="instruction" id="paper-status" role="status">${studio.coated?t('The surface is ready. Continue to discover the colors.','Bề mặt đã sẵn sàng. Tiếp tục khám phá màu sắc.'):t('Press the button, or focus it and press Enter. The texture will change.','Nhấn nút hoặc đưa tiêu điểm vào nút rồi nhấn Enter. Kết cấu giấy sẽ thay đổi.')}</p></div></div>`;
 if(studio.stage===2)return `<div class="work-title"><div><h2>${t('A palette grown from the earth.','Bảng màu sinh ra từ thiên nhiên.')}</h2><p>${t('Inspect each pigment. Its source is part of what you are learning.','Khám phá từng sắc tố. Nguồn gốc của màu cũng là điều bạn đang học.')}</p></div><span class="micro">${studio.inspected.length}/5 ${t('discovered','đã khám phá')}</span></div><div class="pigment-grid">${ps.map((p,i)=>`<button class="pigment ${i===pigmentIndex?'active':''}" data-pigment="${i}" aria-pressed="${i===pigmentIndex}"><span class="pigment-dot" style="background:${p.color}"></span><strong>${p.name}</strong><small>${p.source} ${studio.inspected.includes(i)?'✓':''}</small></button>`).join('')}</div><div class="pigment-story" aria-live="polite"><h3>${ps[pigmentIndex].name}</h3><p>${ps[pigmentIndex].body}</p></div>`;
 if(studio.stage===3)return `<div class="work-title"><div><h2>${t('One impression at a time.','Từng dấu in một.')}</h2><p>${studio.layers<5?t('Select a block, align the guides, then press to transfer the color.','Chọn ván, căn dấu, rồi ép để chuyển màu.'):t('All five impressions are complete. Your painting is ready to reveal.','Cả năm lớp đã hoàn tất. Tranh đã sẵn sàng để mở ra.')}</p></div><span class="micro">${a.en} · ${studio.layers}/5 ${t('layers','lớp')}</span></div><div class="print-workspace"><div><div class="printing-table" id="printing-table" tabindex="0" role="group" aria-label="${t('Alignment area. Use arrow keys to move the block; Enter to print.','Vùng căn dấu. Dùng phím mũi tên để di chuyển ván; Enter để in.')}"><div class="print-paper"><canvas id="print-canvas" width="900" height="600" role="img" aria-label="${esc(a.en)} — ${studio.layers}/5 ${t('color layers printed','lớp màu đã in')}"></canvas></div><div class="alignment-block" id="alignment-block" style="transform:translate(${studio.offsetX}px,${studio.offsetY}px)" ${studio.layers===5?'hidden':''}></div></div><p class="instruction">${t('Drag anywhere on the table, or use the arrow buttons / keyboard. Align within 4 px.','Kéo trên bàn in, hoặc dùng nút / phím mũi tên. Căn trong phạm vi 4 px.')} <span id="offset-label">X: ${studio.offsetX}, Y: ${studio.offsetY}</span></p><div class="align-controls" aria-label="${t('Keyboard alternative to dragging','Thay thế thao tác kéo')}"><button data-move="left" aria-label="${t('Move left 2 pixels','Sang trái 2 pixel')}">←</button><button data-move="up" aria-label="${t('Move up 2 pixels','Lên 2 pixel')}">↑</button><button data-move="down" aria-label="${t('Move down 2 pixels','Xuống 2 pixel')}">↓</button><button data-move="right" aria-label="${t('Move right 2 pixels','Sang phải 2 pixel')}">→</button><button id="align" style="padding:6px 12px">${t('Align to guides','Căn theo dấu')}</button></div></div><div class="print-controls"><div class="eyebrow">${t('Your printing blocks','Các ván in của bạn')}</div><div class="block-choices">${ps.map((p,i)=>`<button class="block-choice ${studio.block===i?'active':''}" data-block="${i}" aria-pressed="${studio.block===i}" ${i<studio.layers||(studio.mode==='guided'&&i!==studio.layers)?'disabled':''}><span class="dot" style="background:${p.color}"></span>${i<studio.layers?'✓ ':''}${p.name}</button>`).join('')}</div><h3>${studio.layers===5?t('The story comes together.','Câu chuyện đã thành hình.'):ps[studio.block].name}</h3><p>${studio.layers===5?t('Color areas and black contours have joined to form your finished study.','Các mảng màu và nét đen đã hợp thành bản nghiên cứu hoàn chỉnh.'):ps[studio.block].body}</p><div class="progress" role="progressbar" aria-valuenow="${studio.layers}" aria-valuemin="0" aria-valuemax="5" aria-label="${t('Printed layers','Các lớp đã in')}"><span style="width:${studio.layers*20}%"></span></div><span class="micro">${studio.layers} / 5 ${t('impressions complete','lớp in hoàn tất')}</span><p id="print-feedback" class="feedback" role="status">${studio.layers===5?t('✓ All layers printed. Continue to reveal your painting.','✓ Đã in mọi lớp. Tiếp tục để mở tranh.'):studio.mode==='guided'?t('Match the red registration marks, then print the highlighted block.','Căn khớp các dấu đỏ, rồi in ván đang được chọn.'):t('Choose the next color using what you learned.','Chọn màu tiếp theo dựa trên điều đã học.')}</p><button class="btn" id="press" ${studio.layers===5?'disabled':''}>${t('Press & lift the block','Ép và nhấc ván in')} ↓</button><button class="undo" id="undo" ${!studio.layers?'disabled':''}>↶ ${t('Undo last impression','Hoàn tác lớp in trước')}</button>${studio.mode==='guided'?`<div class="hint">${t('Why alignment matters: each block adds just one part of the picture. Registration helps the colors meet the final black contours.','Vì sao cần căn dấu: mỗi ván chỉ in một phần bức tranh. Căn dấu giúp màu khớp với đường viền đen cuối cùng.')}</div>`:''}</div></div>`;
 return `<div class="reveal"><figure class="print-sheet"><span class="tape"></span>${img(studio.art)}<figcaption class="sheet-caption"><span>${a.en}</span><span>${t('Your digital study','Bản nghiên cứu số của bạn')}</span></figcaption></figure><div><div class="eyebrow">${t('The final reveal','Mở bản in hoàn chỉnh')}</div><h2>${t('You made<br>an impression.','Bạn đã tạo<br>một dấu ấn.')}</h2><p>${aText(a.meaning)}</p><p style="margin-top:16px">${t('Five layers, one story. Your print is ready for a place in your exhibition.','Năm lớp màu, một câu chuyện. Bản in đã sẵn sàng có chỗ trong triển lãm của bạn.')}</p><div class="actions"><button class="btn" id="download">${t('Save image','Lưu hình ảnh')} ↓</button><a class="text-link" href="ExhibitionPage.html">${t('Visit your exhibition','Đến triển lãm của bạn')} ${arrow}</a></div></div></div>`;
}
function printWorkshop(){const labels=[t('Choose','Chọn tranh'),t('Prepare paper','Chuẩn bị giấy'),t('Discover colors','Khám phá màu'),t('Print layers','In từng lớp'),t('Reveal','Mở tranh')];return `<main id="main" class="wrap"><section class="page-head"><div class="breadcrumb">Dong Ho / ${t('Printmaking workshop','Xưởng thực hành in')}</div><div class="studio-head"><div><div class="eyebrow">${t('Take a seat at the printing table','Mời bạn ngồi vào bàn in')}</div><h1>${t('Make a story your own.','Tự tay in một câu chuyện.')}</h1></div><div><label class="mode-label" for="mode">${t('YOUR LEARNING MODE','CHẾ ĐỘ HỌC CỦA BẠN')}</label><select id="mode"><option value="guided" ${studio.mode==='guided'?'selected':''}>${t('Guided · with hints','Hướng dẫn · có gợi ý')}</option><option value="independent" ${studio.mode==='independent'?'selected':''}>${t('Independent · test yourself','Tự thực hành · thử kiến thức')}</option></select></div></div></section><nav class="stepper" aria-label="${t('Workshop progress','Tiến trình thực hành')}">${labels.map((v,i)=>`<button data-step="${i}" class="${i===studio.stage?'active':''}" ${i>studio.stage?'disabled':''} ${i===studio.stage?'aria-current="step"':''}><span class="num">${i<studio.stage?'✓':i+1}</span>${v}</button>`).join('')}</nav><section id="work-content" class="fade-in">${stepContent()}</section>${studio.stage<4?`<div class="studio-footer"><button class="text-link" id="back" ${studio.stage===0?'disabled':''}>← ${t('Previous step','Bước trước')}</button><span class="micro">${t('Your progress is saved on this browser when storage is available.','Tiến trình được lưu trong trình duyệt khi bộ nhớ khả dụng.')}</span><button class="btn" id="continue" ${(studio.stage===1&&!studio.coated)||(studio.stage===2&&studio.inspected.length<5)||(studio.stage===3&&studio.layers<5)?'disabled':''}>${studio.stage===3?t('Reveal my painting','Mở bản in của tôi'):t('Continue','Tiếp tục')} →</button></div>`:''}<p class="process-note">${t('Educational reconstruction: digital color masks and alignment adapt a hand-printing process. See Sources for the documented sequence and differences from a real workshop.','Tái dựng giáo dục: lớp màu số và căn chỉnh được điều chỉnh từ quy trình in tay. Xem Nguồn để biết thứ tự in được ghi nhận và khác biệt với xưởng thật.')}</p><button class="undo" id="restart">${t('Start a new print','Bắt đầu bản in mới')}</button></main>`;}
const quizzes=()=>[
 {q:t('Which impression completes the print?','Lớp in nào hoàn thiện bức tranh?'),options:[t('The black outlines','Đường nét đen'),t('The first red layer','Lớp đỏ đầu tiên'),t('The paper coating','Lớp quét giấy')],answer:0,why:t('The final black-outline block defines the contours after the color impressions. The shell coating prepares the paper before printing.','Ván nét đen cuối cùng xác định đường viền sau các lớp màu. Lớp shell coating chuẩn bị giấy trước khi in.')},
 {q:t('What gives shell coating paper its characteristic surface?','Điều gì tạo bề mặt đặc trưng cho giấy shell coating?'),options:[t('A plastic film','Một màng nhựa'),t('A coating containing shell powder','Lớp quét chứa bột vỏ sò'),t('An extra carved woodblock','Một ván khắc bổ sung')],answer:1,why:t('Powdered shells are part of the special shell coating paper coating. This preparation is distinct from a white color impression.','Bột vỏ sò là thành phần lớp quét shell coating đặc trưng. Công đoạn này khác với in lớp màu trắng.')},
 {q:t('What can the cat in Mouse Wedding suggest?','Mèo trong Mouse Wedding có thể gợi điều gì?'),options:[t('An exact historical wedding','Một đám cưới lịch sử chính xác'),t('Only a friendly pet','Chỉ là vật nuôi thân thiện'),t('Unequal power, in a common reading','Quyền lực bất bình đẳng, theo cách đọc phổ biến')],answer:2,why:t('A familiar interpretation sees the gift-receiving cat as a powerful figure. Folk paintings can support multiple readings; symbols are not fixed historical facts.','Một cách đọc quen thuộc xem mèo nhận lễ là kẻ có quyền. Tranh dân gian có thể có nhiều cách hiểu; biểu tượng không phải sự kiện lịch sử cố định.')}
];
function quiz(){const qs=quizzes();if(quizIndex>=qs.length){const score=quizAnswers.filter((v,i)=>v===qs[i].answer).length;return `<div class="quiz-top"><h2>${t('Your curiosity leaves a mark.','Sự tò mò của bạn để lại dấu ấn.')}</h2><small>${score} / 3 ${t('correct','đúng')}</small></div><p>${t('You have explored materials, printing, and meaning. There is always another detail to discover.','Bạn đã khám phá chất liệu, kỹ thuật và ý nghĩa. Luôn còn chi tiết khác để tìm hiểu.')}</p><button class="text-link" id="retry-quiz" style="margin-top:20px">${t('Try the challenge again','Thử lại thử thách')} ↺</button>`;}const q=qs[quizIndex],answered=quizAnswers[quizIndex]!==undefined;return `<div class="quiz-top"><h2>${t('A little reflection.','Một chút suy ngẫm.')}</h2><small>${t('CULTURAL CHALLENGE','THỬ THÁCH VĂN HÓA')} ${quizIndex+1}/3</small></div><h3>${q.q}</h3><div class="quiz-options">${q.options.map((v,i)=>`<button data-answer="${i}" ${answered?'disabled':''} class="${answered&&i===q.answer?'correct':answered&&i===quizAnswers[quizIndex]?'incorrect':''}">${answered&&i===q.answer?'✓ ':answered&&i===quizAnswers[quizIndex]?'↻ ':''}${v}</button>`).join('')}</div><div class="quiz-feedback" role="status">${answered?(quizAnswers[quizIndex]===q.answer?t('That’s right. ','Đúng rồi. '):t('A useful discovery. ','Một điều đáng học. '))+q.why:''}</div>${answered?`<button class="text-link" id="next-question">${quizIndex===2?t('See my reflection','Xem kết quả'):t('Next question','Câu tiếp theo')} →</button>`:''}`;}
function printExhibition(){const c=completed&&artwork[completed.art]?completed:null;return `<main id="main" class="wrap"><section class="page-head"><div class="breadcrumb">Dong Ho / ${t('Your exhibition','Triển lãm của bạn')}</div><div class="eyebrow">${t('A place for your first impression','Nơi dành cho dấu in đầu tiên')}</div><h1>${c?t('A story, carried forward by you.','Câu chuyện được bạn tiếp nối.'):t('Your story is waiting to be printed.','Câu chuyện đang chờ bạn in.')}</h1><p>${t('Pause, look back, and see what your hands have learned.','Dừng lại, nhìn lại và xem đôi tay bạn đã học được gì.')}</p></section><section class="exhibit-grid"><div>${c?`<figure class="print-sheet" style="transform:rotate(-2deg)">${img(c.art)}<figcaption class="sheet-caption"><span>${artwork[c.art].en}</span><span>${t('Five impressions · one story','Năm lớp in · một câu chuyện')}</span></figcaption></figure><div class="exhibition-caption"><div><h3>${artwork[c.art].en}</h3><p>${t('Digital study printed by','Bản nghiên cứu số do')} <strong id="artist-display">${esc(c.name||t('a curious maker','một người yêu khám phá'))}</strong></p></div><button class="btn secondary" id="download">${t('Save image','Lưu hình ảnh')} ↓</button></div>`:`<div class="empty-art">${img('chickens')}<div><h2>${t('This space is yours.','Không gian này là của bạn.')}</h2><p>${t('Complete your first print in the workshop to hang it here.','Hoàn thành bản in đầu tiên tại xưởng để trưng bày ở đây.')}</p><a class="btn" href="WorkshopPage.html">${t('Make my first print','In bức tranh đầu tiên')} →</a></div></div>`}</div><div><h2 style="font-size:2.4rem">${c?t('Five steps.<br>A new connection.','Năm bước.<br>Một kết nối mới.'):t('A journey from paper to story.','Hành trình từ giấy đến câu chuyện.')}</h2>${c?`<label for="artist-name" class="micro" style="display:block;margin-top:20px">${t('ADD YOUR NAME TO THE EXHIBITION (OPTIONAL)','THÊM TÊN VÀO TRIỂN LÃM (TÙY CHỌN)')}</label><input class="name-input" id="artist-name" maxlength="50" placeholder="${t('Your name','Tên của bạn')}" value="${esc(c.name||'')}"><p class="micro" id="name-status" role="status">${t('Saved only on this browser.','Chỉ lưu trên trình duyệt này.')}</p>`:''}<div class="process-list">${[t('Choose a story that speaks to you','Chọn câu chuyện gợi cảm hứng'),t('Prepare the bark paper with shell coating','Chuẩn bị giấy bark và lớp shell coating'),t('Discover the natural pigment sources','Khám phá nguồn màu tự nhiên'),t('Align and print; add black outlines last','Căn dấu và in; thêm nét đen cuối cùng'),t('Reveal the image and its meaning','Mở bản in cùng ý nghĩa')].map((v,i)=>`<p><span>${c?'✓':'0'+(i+1)}</span>${v}</p>`).join('')}</div><div class="actions"><a class="text-link" href="WorkshopPage.html" id="another-print">${t('Print another story','In câu chuyện khác')} ${arrow}</a><a class="text-link" href="ExplorePage.html">${t('Keep exploring','Tiếp tục khám phá')} →</a></div></div></section><section class="quiz" id="quiz" aria-label="${t('Cultural learning quiz','Câu hỏi văn hóa')}">${quiz()}</section></main>`;}
function toast(message){const el=$('#toast');el.textContent=message;el.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.hidden=true,4500);}
let activeSpeech=null,speechGeneration=0;
function resetNarrationButton(){const button=$('#narrate');if(button){button.setAttribute('aria-pressed','false');button.textContent='▷ Listen to this page';}}
function stopSpeech(){const previous=activeSpeech;activeSpeech=null;speechGeneration++;if('speechSynthesis' in window)speechSynthesis.cancel();narrating=false;previous?.onState?.('idle');resetNarrationButton();}
function speak(text,options={}){
 stopSpeech();
 if(!('speechSynthesis' in window)||typeof SpeechSynthesisUtterance==='undefined'){options.onState?.('unavailable');if(page!=='history')toast('Narration is unavailable in this browser. The written words are still here to read.');return false;}
 const generation=++speechGeneration,u=new SpeechSynthesisUtterance(text);u.lang='en-GB';u.rate=.9;const voice=speechSynthesis.getVoices().find(v=>v.lang.toLowerCase().startsWith('en'));if(voice)u.voice=voice;
 activeSpeech={generation,onState:options.onState};
 const state=value=>{if(generation!==speechGeneration)return;options.onState?.(value);};
 u.onstart=()=>state('playing');u.onpause=()=>state('paused');u.onresume=()=>state('playing');
 u.onend=()=>{if(generation!==speechGeneration)return;narrating=false;activeSpeech=null;options.onState?.('ended');resetNarrationButton();};
 u.onerror=()=>{if(generation!==speechGeneration)return;narrating=false;activeSpeech=null;options.onState?.('unavailable');resetNarrationButton();};
 try{if(speechSynthesis.paused)speechSynthesis.resume();speechSynthesis.speak(u);}catch{activeSpeech=null;narrating=false;state('unavailable');resetNarrationButton();return false;}narrating=true;state('playing');const button=$('#narrate');if(button){button.setAttribute('aria-pressed','true');button.textContent='■ Stop narration';}return true;
}
function pauseSpeech(){if(!activeSpeech||!('speechSynthesis' in window))return;speechSynthesis.pause();activeSpeech.onState?.('paused');}
function resumeSpeech(){if(!activeSpeech||!('speechSynthesis' in window))return;speechSynthesis.resume();activeSpeech.onState?.('playing');}
function toggleAmbient(){if(ambientOn){ambient?.close();ambient=null;ambientOn=false;}else{const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return toast(t('Ambient audio is unavailable.','Âm thanh nền chưa được hỗ trợ.'));try{ambient=new AC();[174.61,261.63,349.23].forEach((f,i)=>{const o=ambient.createOscillator(),g=ambient.createGain();o.type='sine';o.frequency.value=f;g.gain.value=.008/(i+1);o.connect(g);g.connect(ambient.destination);o.start();});ambientOn=true;}catch{return toast(t('Audio could not start.','Chưa thể bật âm thanh.'));}}const b=$('#ambient');b.setAttribute('aria-pressed',ambientOn);b.innerHTML=`${ambientOn?'♫':'♩'} <span>${t(ambientOn?'Sound on':'Sound off',ambientOn?'Có âm':'Tắt âm')}</span>`;toast(t(ambientOn?'Gentle synthesized ambience on.':'Ambient sound off.',ambientOn?'Đã bật âm nền tổng hợp dịu nhẹ.':'Đã tắt âm nền.'));}
function render(restore){if(typeof disposeModernHome==='function')disposeModernHome();stopSpeech();document.body.dataset.view=page;document.documentElement.lang='en';document.documentElement.style.setProperty('--font',safeGet('dongho-large',false)?'18px':'16px');document.title=`${names()[page]} · Dong Ho — ${t('The Living Printmaking Studio','Xưởng tranh dân gian sống')}`;document.body.innerHTML=`<a class="skip" href="#main">${t('Skip to content','Đến nội dung chính')}</a>${header()}${page==='home'?'':backToStudio()}${({home,history:heritagePage,explore,workshop,exhibition})[page]()}${footer()}`;bind();if(restore){const e=$(restore);if(e)e.focus({preventScroll:true});}updateTranscript();if(page==='workshop'&&creationMode==='print'&&studio.stage===3)drawPrint(studio.layers);}
function updateTranscript(){if(!$('#transcript'))return;const parts=$$('main h1,main h2,main h3,main p').filter(e=>!e.closest('.process-note,.chapter-transcript,.chapter-sources')).map(e=>e.textContent.trim()).filter(Boolean);$('#transcript').textContent=parts.join(' ');}
function arrowTabs(selector,attr){$$(selector).forEach(el=>el.addEventListener('keydown',e=>{const items=$$(selector);const i=items.indexOf(el);let next;if(e.key==='ArrowRight')next=(i+1)%items.length;else if(e.key==='ArrowLeft')next=(i-1+items.length)%items.length;else if(e.key==='Home')next=0;else if(e.key==='End')next=items.length-1;else return;e.preventDefault();items[next].click();const target=$(`[${attr}="${items[next].getAttribute(attr)}"]`);target?.focus({preventScroll:true});}));}
function bind(){
 bindStudioNavigation();
 $('#menu').onclick=()=>{const open=$('.nav').classList.toggle('open');$('#menu').setAttribute('aria-expanded',open);};
 $('#text-size').onclick=()=>{save('dongho-large',!safeGet('dongho-large',false));render('#text-size');};
 $('#ambient').onclick=toggleAmbient;
 if($('#narrate'))$('#narrate').onclick=()=>{if(narrating){stopSpeech();$('#narrate').setAttribute('aria-pressed','false');$('#narrate').textContent='▷ '+t('Listen to this page','Nghe nội dung trang');}else{speak($('#transcript').textContent);if(narrating){$('#narrate').setAttribute('aria-pressed','true');$('#narrate').textContent='■ '+t('Stop narration','Dừng đọc');}}};
 if(page==='home')bindModernHome();
 if(page==='history')bindHeritage();
 if(page==='explore'){
  $$('[data-art]').forEach(el=>el.onclick=()=>{selectedArt=el.dataset.art;selectedDetail=0;zoom=1;render('#art-tab-'+selectedArt);});arrowTabs('[data-art]','data-art');
  $$('[data-detail]').forEach((el,i)=>el.onclick=()=>{selectedDetail=Number(el.dataset.detail);const wasList=!!el.closest('.detail-list');render(wasList?`.detail-list [data-detail="${selectedDetail}"]`:`.hotspot[data-detail="${selectedDetail}"]`);});
  const setZoom=n=>{zoom=Math.min(1.75,Math.max(1,n));$('#zoom-content').style.transform=`scale(${zoom})`;$('#zoom-label').textContent=Math.round(zoom*100)+'%';$$('.hotspot').forEach(e=>{e.style.visibility=zoom>1?'hidden':'';});};
  $('#zoom-in').onclick=()=>setZoom(zoom+.25);$('#zoom-out').onclick=()=>setZoom(zoom-.25);$('#zoom-reset').onclick=()=>setZoom(1);
  $('#listen-detail').onclick=()=>speak(aText(artwork[selectedArt].details[selectedDetail].body));
  $('#make-this').onclick=()=>{creationMode='print';save('dongho-creation-mode','print');if(studio.art!==selectedArt)studio={...studio,stage:0,art:selectedArt,layers:0,coated:false,inspected:[],block:0,offsetX:14,offsetY:-10};persistStudio();};
 }
 if(page==='workshop'){bindCreationSwitcher();if(creationMode==='free'){bindDrawing();bindDrawingGuide();}else bindStudio();}
 if(page==='exhibition'&&showingOriginalDrawing()){bindDrawingExhibition();}
 else if(page==='exhibition'){
  $('#download')?.addEventListener('click',()=>download(completed.art,completed.name));
  $('#artist-name')?.addEventListener('input',e=>{completed.name=e.target.value;save('dongho-completed',completed);$('#artist-display').textContent=completed.name||t('a curious maker','một người yêu khám phá');$('#name-status').textContent=t('Name saved on this browser.','Đã lưu tên trên trình duyệt này.');});
  $('#another-print').onclick=()=>{studio={...studio,stage:0,layers:0,coated:false,inspected:[],block:0,offsetX:14,offsetY:-10};persistStudio();};bindQuiz();
 }
}
function bindQuiz(){$$('[data-answer]').forEach(el=>el.onclick=()=>{quizAnswers[quizIndex]=Number(el.dataset.answer);$('#quiz').innerHTML=quiz();bindQuiz();updateTranscript();});$('#next-question')?.addEventListener('click',()=>{quizIndex++;$('#quiz').innerHTML=quiz();bindQuiz();$('#quiz').setAttribute('tabindex','-1');$('#quiz').focus({preventScroll:true});});$('#retry-quiz')?.addEventListener('click',()=>{quizIndex=0;quizAnswers=[];$('#quiz').innerHTML=quiz();bindQuiz();});}
function stageTo(n){studio.stage=n;if(n===4)save('dongho-exhibit-kind','print');if(n===2&&!studio.inspected.includes(pigmentIndex))studio.inspected.push(pigmentIndex);if(n===4){completed={art:studio.art,name:completed?.name||'',date:new Date().toISOString()};save('dongho-completed',completed);}persistStudio();render();$('#work-content').setAttribute('tabindex','-1');$('#work-content').focus({preventScroll:true});}
function bindStudio(){
 $('#mode').onchange=e=>{studio.mode=e.target.value;persistStudio();render('#mode');};
 $$('[data-step]').forEach(el=>el.onclick=()=>stageTo(Number(el.dataset.step)));
 $$('[data-choose]').forEach(el=>el.onclick=()=>{if(studio.art!==el.dataset.choose){studio.art=el.dataset.choose;studio.layers=0;studio.block=0;}persistStudio();render(`[data-choose="${studio.art}"]`);});
 $('#coat')?.addEventListener('click',()=>{studio.coated=true;persistStudio();$('#paper-preview').classList.add('coated');$('#paper-preview').textContent=t('Coated paper · ready to print','Coated paper · đã sẵn sàng');$('#coat').disabled=true;$('#paper-status').textContent=t('✓ Paper prepared. The coating gives the sheet its distinctive surface.','✓ Giấy đã sẵn sàng. Lớp shell coating tạo bề mặt đặc trưng.');$('#continue').disabled=false;});
 $$('[data-pigment]').forEach(el=>el.onclick=()=>{pigmentIndex=Number(el.dataset.pigment);if(!studio.inspected.includes(pigmentIndex))studio.inspected.push(pigmentIndex);persistStudio();render(`[data-pigment="${pigmentIndex}"]`);});
 $('#continue')?.addEventListener('click',()=>stageTo(Math.min(4,studio.stage+1)));
 $('#back')?.addEventListener('click',()=>stageTo(Math.max(0,studio.stage-1)));
 $('#restart').onclick=()=>{studio={...studio,stage:0,layers:0,coated:false,inspected:[],block:0,offsetX:14,offsetY:-10};persistStudio();render('#work-content');toast(t('A fresh sheet is ready. Your last exhibition print is kept.','Tờ giấy mới đã sẵn sàng. Tranh triển lãm trước vẫn được giữ.'));};
 $('#download')?.addEventListener('click',()=>download(studio.art,completed?.name));
 if(studio.stage===3){
  $$('[data-block]').forEach(el=>el.onclick=()=>{studio.block=Number(el.dataset.block);persistStudio();render(`[data-block="${studio.block}"]`);});
  $$('[data-move]').forEach(el=>el.onclick=()=>move(el.dataset.move));
  $('#align').onclick=()=>{studio.offsetX=0;studio.offsetY=0;updateAlignment();$('#print-feedback').textContent=t('✓ Registration aligned. Ready to print.','✓ Dấu đã khớp. Sẵn sàng in.');};
  $('#press').onclick=press;
  $('#undo').onclick=()=>{studio.layers=Math.max(0,studio.layers-1);studio.block=studio.layers;persistStudio();render('#undo');$('#print-feedback').textContent=t('Last impression removed. You can print it again.','Đã gỡ lớp cuối. Bạn có thể in lại.');};
  const table=$('#printing-table');table.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();move(e.key.replace('Arrow','').toLowerCase());}else if(e.key==='Enter'||e.key===' '){e.preventDefault();press();}});
  let drag=null;table.onpointerdown=e=>{if(studio.layers===5)return;drag={x:e.clientX,y:e.clientY,ox:studio.offsetX,oy:studio.offsetY};table.setPointerCapture(e.pointerId);};table.onpointermove=e=>{if(!drag)return;studio.offsetX=Math.max(-45,Math.min(45,Math.round(drag.ox+e.clientX-drag.x)));studio.offsetY=Math.max(-45,Math.min(45,Math.round(drag.oy+e.clientY-drag.y)));updateAlignment();};table.onpointerup=table.onpointercancel=()=>drag=null;
 }
}
function move(dir){if(studio.layers===5)return;const delta={left:[-2,0],right:[2,0],up:[0,-2],down:[0,2]}[dir];studio.offsetX=Math.max(-45,Math.min(45,studio.offsetX+delta[0]));studio.offsetY=Math.max(-45,Math.min(45,studio.offsetY+delta[1]));updateAlignment();}
function updateAlignment(){persistStudio();$('#alignment-block').style.transform=`translate(${studio.offsetX}px,${studio.offsetY}px)`;$('#offset-label').textContent=`X: ${studio.offsetX}, Y: ${studio.offsetY}`;}
function press(){if(studio.layers>=5)return;if(studio.block!==studio.layers){$('#print-feedback').textContent=t('This block is out of sequence. Recall: red → plant color → yellow → white → black. Choose another block; your paper is unchanged.','Ván chưa đúng thứ tự. Nhớ lại: đỏ → xanh thực vật → vàng → trắng → đen. Chọn ván khác; giấy vẫn nguyên.');return;}if(Math.abs(studio.offsetX)>4||Math.abs(studio.offsetY)>4){$('#print-feedback').textContent=t('The marks are not aligned yet. Move the block or choose “Align to guides”, then try again. No color was transferred.','Dấu chưa khớp. Di chuyển ván hoặc chọn “Căn theo dấu” rồi thử lại. Chưa chuyển màu.');return;}studio.layers++;studio.block=Math.min(4,studio.layers);studio.offsetX=12;studio.offsetY=-8;persistStudio();render('#press');$('#print-feedback').textContent=studio.layers===5?t('✓ The black contours complete your print. Ready for the reveal.','✓ Nét đen đã hoàn thiện bản in. Sẵn sàng mở tranh.'):t(`✓ Impression ${studio.layers}/5 transferred. Re-align for the next block.`,`✓ Đã chuyển lớp ${studio.layers}/5. Căn lại cho ván tiếp theo.`);$('.print-paper').classList.add('press-flash');}
const bitmapCache={};
async function bitmap(key){if(bitmapCache[key])return bitmapCache[key];const image=new Image();image.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(ART_DATA[key]);await image.decode();const c=document.createElement('canvas');c.width=900;c.height=600;const ctx=c.getContext('2d',{willReadFrequently:true});ctx.drawImage(image,0,0);const data=ctx.getImageData(0,0,900,600),cats=new Uint8Array(900*600);for(let p=0;p<cats.length;p++){let i=p*4,r=data.data[i],g=data.data[i+1],b=data.data[i+2];if(r<110&&g<110&&b<100)cats[p]=5;else if(g>r*.99&&g>b*1.06&&r<180)cats[p]=2;else if(r>g*1.35&&g>b*1.1)cats[p]=1;else if(r>210&&g>210&&b>195)cats[p]=4;else if(r-g>32&&r>150&&b<180)cats[p]=3;else cats[p]=0;}return bitmapCache[key]={image,data,cats};}
async function drawPrint(layers){const key=studio.art;const target=$('#print-canvas');if(!target)return;const b=await bitmap(key);if(!target.isConnected)return;const copy=new ImageData(new Uint8ClampedArray(b.data.data),900,600);for(let p=0;p<b.cats.length;p++)if(b.cats[p]>layers){const i=p*4;copy.data[i]=236;copy.data[i+1]=221;copy.data[i+2]=186;}target.getContext('2d').putImageData(copy,0,0);}
async function download(key,name){try{const b=await bitmap(key);const c=document.createElement('canvas');c.width=1200;c.height=900;const ctx=c.getContext('2d');ctx.fillStyle='#f5ebd7';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(b.image,60,40,1080,720);ctx.fillStyle='#292620';ctx.font='28px Georgia';ctx.fillText(artwork[key].en,60,810);ctx.font='16px Arial';ctx.fillText(t('Contemporary digital study · Dong Ho — The Living Printmaking Studio','Nghiên cứu số đương đại · Dong Ho — Xưởng tranh dân gian sống'),60,845);if(name)ctx.fillText(t('Printed by: ','Người in: ')+name,60,875);const a=document.createElement('a');a.download=`Dong-Ho-${key}.png`;a.href=c.toDataURL('image/png');a.click();toast(t('Your PNG image is ready to save.','Ảnh PNG đã sẵn sàng để lưu.'));}catch{toast(t('Image export is unavailable in this browser. Try a current browser.','Trình duyệt chưa thể xuất ảnh. Hãy thử trình duyệt mới.'));}}
window.addEventListener('pagehide',()=>{finishDrawingStroke();stopSpeech();ambient?.close();});
render();









